SELECT result.c0 AS "n" FROM (SELECT t.c0 AS c0 FROM (SELECT CAST(COUNT(*) AS BIGINT) AS c0 FROM (SELECT w.c0 AS c0, w.c1 AS c1, w.c2 AS c2, make_timestamp(w.__start) AS c3, make_timestamp(w.__start + 10000000) AS c4 FROM (SELECT t.*, (epoch_us(t.c1) - ((epoch_us(t.c1) % 10000000 + 10000000) % 10000000)) - k.i * 10000000 AS __start FROM (SELECT "id" AS c0, "ts" AS c1, "amount" AS c2 FROM "events") t CROSS JOIN range(1) k(i) WHERE CASE WHEN isfinite(t.c1) THEN TRUE ELSE error('OUTSIDE_CONTRACT: finite TIMESTAMP required') END) w) t) t) result;
